import os

# Fix chart.html
with open('/app/output/chart.html', 'r') as f:
    html = f.read()

# Instead of tab-active, we want to use specific classes for pills.
# Remove generic tab logic conflict by replacing data-tab-group with data-pill-group
html = html.replace('data-tab-group="chart-timeframe"', 'data-pill-group="chart-timeframe"')
html = html.replace('data-tab-target="tf-', 'data-pill-target="tf-')

html = html.replace('data-tab-group="chart-financials"', 'data-pill-group="chart-financials"')
html = html.replace('data-tab-target="fin-', 'data-pill-target="fin-')

script_replacement = """
document.querySelectorAll('[data-pill-target]').forEach(button => {
    button.addEventListener('click', () => {
        const group = button.getAttribute('data-pill-group');
        const targetId = button.getAttribute('data-pill-target');

        document.querySelectorAll(`[data-pill-group="${group}"]`).forEach(b => {
            b.classList.remove('bg-brand-surfaceHover', 'text-white');
            b.classList.add('text-brand-textMuted');
        });
        button.classList.remove('text-brand-textMuted');
        button.classList.add('bg-brand-surfaceHover', 'text-white');

        if (targetId) {
            document.querySelectorAll(`[data-tab-content-group="${group}"]`).forEach(c => {
                c.classList.remove('active');
                c.classList.add('hidden');
            });
            const content = document.getElementById(targetId);
            if(content) {
                content.classList.remove('hidden');
                content.classList.add('active');
            }
        }
    });
});
"""

html = html.replace('// Tab functionality for timeframe and financials', script_replacement + '\n// Tab functionality for timeframe and financials')

with open('/app/output/chart.html', 'w') as f:
    f.write(html)

# Fix ideas.html
with open('/app/output/ideas.html', 'r') as f:
    html = f.read()

html = html.replace('data-tab-group="ideas-feed"', 'data-pill-group="ideas-feed"')
html = html.replace('data-tab-target="feed-', 'data-pill-target="feed-')

with open('/app/output/ideas.html', 'w') as f:
    f.write(html)

EOF
